right = pd.DataFrame({'timestamp': pd.to_datetime(['2020-01-01', '2020-01-02', '2020-01-03'], tz='UTC'), 'other_value': [4, 5, 6]})

# Merge DataFrames
result = pd.merge_asof(left, right, left_index=True, right_on='timestamp')

